1	/**
2	 * Builds the whole washer world in absolute coordinates around the master course.
3	 * Drum A (01–02) → chute → whirlpool basin room (03) → gold ring pipe (04) → perforated current tube
4	 * (05) → arch hall (06) → washer tube + deep plunge (07) → Final Spin Chamber (08–11).
5	 */
6	import * as THREE from 'three';
7	import { RoundedBoxGeometry } from 'three/examples/jsm/geometries/RoundedBoxGeometry.js';
8	import { Course, WORLD, funnelY } from './course';
9	import { perforatedMetal, gold, goldRibbed, chrome, glass, painted, canvasTexture, washerTubeEnv, withFarGlow, withTubeStrips, withBandShading, withLidShading, nearFrameMaterial, tunnelEndGlowMaterial, farRiverMaterial, marblePano05, marblePanoRotation05, marblePanoMatrix05, type FarGlow, type TubeStrips } from './materials';
10	import { buildTubeGeometry, buildRings, buildRingsAt, buildWallLids, courseTubePath, straightTubePath, tubeCenterAt, ForcedTunnel, bandGeometry, wallLidGeometry, wallLidBasis, nearFrameGeometry } from './tube';
11	import { STAGE_CAM } from '../game/cameraRig';
12	import { far05Debug, farRiverLayout, farRiverGeometry } from './far05'; // path-camera (05 far tunnel block)
13	import { FLOW05, FLOWMAP05, PROJ05 } from '../vfx/waterRibbon';
14	import { createProj05Apron } from '../vfx/proj05Apron'; // Screen 05 test W11 (?flow05=1), advection speed (?flowcam05=1)
15	import { flow05Shared, flow05Textures } from '../vfx/flow05';
16	import { buildLaundryRoom, LaundryRoom } from './laundryRoom';
17	import { buildTowel, TowelMesh } from './towel';
18	
19	export interface Environment {
20	  group: THREE.Group;
21	  update(time: number, dt: number): void;
22	  doorA: THREE.Object3D; // hinge pivot (rotation.y opens)
23	  doorC: THREE.Object3D;
24	  roomA: LaundryRoom & { anchor: THREE.Object3D };
25	  roomC: LaundryRoom & { anchor: THREE.Object3D };
26	  towel: TowelMesh; // on the chamber platform (08–11)
27	  drumTowel: TowelMesh; // bundle wrapped around Benny in drum A (01–02)
28	  laundry: { sock: THREE.Object3D; shirt: THREE.Object3D };
29	  /** groups toggled per scene for performance */
30	  zones: Record<'drumA' | 'basin' | 'tubes' | 'chamber', THREE.Group>;
31	  /** straight 05–07 tunnel axis (camera alignment) */
32	  tubeAxis: { path: import('./tube').TubePath; s0: number; s1: number };
33	}
34	
35	const sm = (a: number, b: number, x: number) => {
36	  const t = THREE.MathUtils.clamp((x - a) / (b - a), 0, 1);
37	  return t * t * (3 - 2 * t);
38	};
39	
40	export function buildEnvironment(course: Course): Environment {
41	  const root = new THREE.Group();
42	  root.name = 'washer_world';
43	  const zones = {
44	    drumA: new THREE.Group(),
45	    basin: new THREE.Group(),
46	    tubes: new THREE.Group(),
47	    chamber: new THREE.Group(),
48	  };
49	  Object.entries(zones).forEach(([k, g]) => { g.name = 'zone_' + k; root.add(g); });
50	  const goldMat = gold();
51	  const goldSoft = gold({ roughness: 0.3, emissive: 0.3 });
52	  const chromeMat = chrome();
53	  const animated: ((t: number, dt: number) => void)[] = [];
54	
55	  // =====================================================================================
56	  // Drum A (01–02)
57	  // =====================================================================================
58	  const dA = WORLD.drumA;
59	  const drumLen = dA.zDoor - dA.zBack;
60	  const drumGeo = new THREE.CylinderGeometry(dA.radius, dA.radius, drumLen, 96, 24, true);
61	  drumGeo.rotateX(Math.PI / 2);
62	  drumGeo.translate(0, 0, (dA.zDoor + dA.zBack) / 2);
63	  const drumMat = perforatedMetal({ color: '#f04fc8', emissive: '#c22aa6', emissiveIntensity: 0.3, slot: 0, repeatU: 54, repeatV: 15, holeSize: 0.44, streaks: 0.15 });
64	  zones.drumA.add(new THREE.Mesh(drumGeo, drumMat));
65	  // back wall with the drain opening
66	  const backShape = new THREE.Shape();
67	  backShape.absarc(0, 0, dA.radius, 0, Math.PI * 2, false);
68	  const drainHole = new THREE.Path();
69	  drainHole.absarc(-0.3, -3.05, 1.85, 0, Math.PI * 2, true);
70	  backShape.holes.push(drainHole);
71	  const backGeo = new THREE.ShapeGeometry(backShape, 48);
72	  backGeo.translate(0, 0, dA.zBack);
73	  const backMat = perforatedMetal({ color: '#e544c4', slot: 0, repeatU: 9, repeatV: 9, holeSize: 0.4, side: THREE.DoubleSide, streaks: 0 });
74	  zones.drumA.add(new THREE.Mesh(backGeo, backMat));
75	  // front wall annulus
76	  const frontShape = new THREE.Shape();
77	  frontShape.absarc(0, 0, dA.radius, 0, Math.PI * 2, false);
78	  const doorHole = new THREE.Path();
79	  doorHole.absarc(0, 0, dA.doorRadius, 0, Math.PI * 2, true);
80	  frontShape.holes.push(doorHole);
81	  const frontGeo = new THREE.ShapeGeometry(frontShape, 64);
82	  frontGeo.translate(0, 0, dA.zDoor);
83	  zones.drumA.add(new THREE.Mesh(frontGeo, perforatedMetal({ color: '#f15ccd', slot: 0, repeatU: 8, repeatV: 8, holeSize: 0.0, side: THREE.DoubleSide, streaks: 0, metalness: 0.85, roughness: 0.18 })));
84	  // gold door ring (thick) + chrome inner lip
85	  const ringA = new THREE.Mesh(new THREE.TorusGeometry(dA.doorRadius + 0.35, 0.48, 24, 96), goldMat);
86	  ringA.position.set(0, 0, dA.zDoor - 0.1);
87	  zones.drumA.add(ringA);
88	  const ringA2 = new THREE.Mesh(new THREE.TorusGeometry(dA.doorRadius + 1.15, 0.22, 16, 96), goldSoft);
89	  ringA2.position.set(0, 0, dA.zDoor - 0.15);
90	  zones.drumA.add(ringA2);
91	  // lifters (gold baffles)
92	  for (const ang of [52, 128, 270]) {
93	    const a = THREE.MathUtils.degToRad(ang);
94	    const lifter = new THREE.Mesh(new RoundedBoxGeometry(1.5, 1.1, drumLen - 1.6, 4, 0.5), goldMat);
95	    lifter.position.set(Math.cos(a) * (dA.radius - 0.45), Math.sin(a) * (dA.radius - 0.45), (dA.zDoor + dA.zBack) / 2 - 0.3);
96	    lifter.rotation.z = a + Math.PI / 2;
97	    zones.drumA.add(lifter);
98	  }
99	  // washer door A (hinged on the left seen from the room: pivot at x=-r)
100	  const doorA = new THREE.Group();
101	  doorA.name = 'doorA_pivot';
102	  doorA.position.set(-(dA.doorRadius + 0.6), 0, dA.zDoor + 0.55);
103	  const doorAInner = new THREE.Group();
104	  doorAInner.position.set(dA.doorRadius + 0.6, 0, 0);
105	  const doorRingA = new THREE.Mesh(new THREE.TorusGeometry(dA.doorRadius + 0.2, 0.42, 20, 80), chromeMat);
106	  const doorGlassA = new THREE.Mesh(new THREE.CircleGeometry(dA.doorRadius + 0.05, 48), glass('#e8f0ff', 0.1));
107	  doorAInner.add(doorRingA, doorGlassA);
108	  doorA.add(doorAInner);
109	  zones.drumA.add(doorA);
110	  // laundry room A outside the door
111	  const roomA = buildLaundryRoom({ floorDrop: 11, palette: 'warm' });
112	  const anchorA = new THREE.Group();
113	  anchorA.position.set(0, 0, dA.zDoor + 0.8);
114	  anchorA.add(roomA.group);
115	  zones.drumA.add(anchorA);
116	  // floating laundry: blue striped sock + pink star T-shirt
117	  const sock = buildSock();
118	  const shirt = buildShirt();
119	  zones.drumA.add(sock, shirt);
120	  // towel bundle around Benny
121	  const drumTowel = buildTowel();
122	  drumTowel.setBundle(1);
123	  zones.drumA.add(drumTowel.mesh);
124	  // chute from drum A drain to the basin rim
125	  // the chute begins exactly where the course passes through the drum's back wall
126	  let sChute0 = course.marks['02_drain'] - 3;
127	  while (course.sample(sChute0).pos.z > dA.zBack + 0.3 && sChute0 < course.stage('03').s0) sChute0 += 0.1;
128	  const sChute1 = course.stage('03').s0 + 0.3;
129	  const chutePath = courseTubePath(course, () => 2.25, 0.55);
130	  const chute = new THREE.Mesh(
131	    buildTubeGeometry(chutePath, sChute0, sChute1, { radial: 36, step: 0.5, vScale: 1 }),
132	    perforatedMetal({ color: '#e94ad0', slot: 0, repeatU: 22, repeatV: 1.6, holeSize: 0.38 }),
133	  );
134	  zones.drumA.add(chute);
135	  zones.drumA.add(buildRings(chutePath, sChute0 + 1.5, sChute1 - 1, 3.2, goldMat, { tube: 0.09 }));
136	
137	  // =====================================================================================
138	  // Whirlpool basin room (03) + backdrop shared with 04
139	  // =====================================================================================
140	  const B = WORLD.basin;
141	  const prof: THREE.Vector2[] = [];
142	  for (let i = 0; i <= 40; i++) {
143	    const r = B.drainRadius * 1.04 + (B.rimRadius + 0.4 - B.drainRadius * 1.04) * (i / 40);
144	    prof.push(new THREE.Vector2(r, funnelY(r) - 0.45));
145	  }
146	  const funnelGeo = new THREE.LatheGeometry(prof, 96);
147	  funnelGeo.translate(B.center.x, 0, B.center.z);
148	  zones.basin.add(new THREE.Mesh(funnelGeo, perforatedMetal({ color: '#e04fd0', slot: 0, repeatU: 60, repeatV: 22, holeSize: 0.3, side: THREE.DoubleSide, streaks: 0 })));
149	  // thick gold drain lip + inner ring (ref 03: concentric gold rings inside the drain)
150	  for (const [rr, tt, dy] of [[B.drainRadius + 0.15, 0.42, 0.1], [B.drainRadius - 0.55, 0.22, -0.9]] as const) {
151	    const lip = new THREE.Mesh(new THREE.TorusGeometry(rr, tt, 18, 96), goldMat);
152	    lip.rotation.x = Math.PI / 2;
153	    lip.position.set(B.center.x, funnelY(B.drainRadius) + dy, B.center.z);
154	    zones.basin.add(lip);
155	  }
156	  const rim = new THREE.Mesh(new THREE.TorusGeometry(B.rimRadius + 0.5, 0.75, 24, 128), goldMat);
157	  rim.rotation.x = Math.PI / 2;
158	  rim.position.set(B.center.x, B.rimY + 0.25, B.center.z);
159	  zones.basin.add(rim);
160	  const rim2 = new THREE.Mesh(new THREE.TorusGeometry(B.rimRadius + 2.1, 0.35, 16, 128), goldSoft);
161	  rim2.rotation.x = Math.PI / 2;
162	  rim2.position.set(B.center.x, B.rimY + 0.35, B.center.z);
163	  zones.basin.add(rim2);
164	  // glossy pink deck around the basin
165	  const deckShape = new THREE.Shape();
166	  deckShape.moveTo(-34, -34); deckShape.lineTo(34, -34); deckShape.lineTo(34, 30); deckShape.lineTo(-34, 30); deckShape.lineTo(-34, -34);
167	  const deckHole = new THREE.Path();
168	  deckHole.absarc(0, 0, B.rimRadius + 0.4, 0, Math.PI * 2, true);
169	  deckShape.holes.push(deckHole);
170	  const deck = new THREE.Mesh(new THREE.ShapeGeometry(deckShape, 64), new THREE.MeshStandardMaterial({ color: '#f36fd6', metalness: 0.5, roughness: 0.2, emissive: '#c43bb0', emissiveIntensity: 0.35, side: THREE.DoubleSide }));
171	  deck.rotation.x = -Math.PI / 2;
172	  deck.position.set(B.center.x, B.rimY + 0.3, B.center.z);
173	  zones.basin.add(deck);
174	  buildBasinBackdrop(zones.basin, goldMat, chromeMat);
175	
176	  // =====================================================================================
177	  // 04 gold ring pipe
178	  // =====================================================================================
179	  const s04 = course.stage('04').s0, s05 = course.stage('05').s0;
180	  const tubeR = (s: number) => course.prop('tube', s);
181	  // the pipe mouth is the drain hole itself: narrow at the lip, opening up as it dives
182	  // the ring tunnel starts just ahead of Benny on the open slide (ref 04), with a flared mouth
183	  const g0 = s04 + 5.0;
184	  const r04 = (s: number) => tubeR(s) + 1.8 * (1 - sm(g0, g0 + 6, s));
185	  const goldPath = courseTubePath(course, r04, 0.9);
186	  const goldPipe = new THREE.Mesh(buildTubeGeometry(goldPath, g0, s05, { radial: 56, step: 0.4 }), goldRibbed(1.25));
187	  zones.tubes.add(goldPipe);
188	  zones.tubes.add(buildRings(goldPath, g0 + 0.2, s05 - 1, 1.6, goldMat, { tube: 0.05, inset: 0.02 }));
189	  // big mouth rings at the drain
190	  for (let i = 0; i < 4; i++) {
191	    const s = g0 + 0.05 + i * 0.3;
192	    zones.tubes.add(buildRings(goldPath, s, s + 0.01, 1, goldMat, { tube: 0.07, extra: 0.4 + i * 0.22 }));
193	  }
194	
195	  // =====================================================================================
196	  // 05–07 perforated tubes (incl. the 06 arch hall and the full 07 plunge)
197	  // =====================================================================================
198	  const s08 = course.stage('08').s0;
199	  const pinkFlow = pinkFlowMaterial();
200	  // refs 05–07: rich saturated magenta→violet glossy pressed metal, dense glowing slot rows, warm light
201	  // far down the tunnel. Own reflection environment (no cyan studio panel) + correct inward normals.
202	  // hot magenta near → violet mid-tunnel → warm yellow-white core at the vanishing point
203	  const tubeGlow: FarGlow = { color: '#ffd08a', near: 48, far: 105, strength: 1.5 };
204	  const wallGlow: FarGlow = { ...tubeGlow, mid: { color: '#8a3cf0', near: 10, far: 42, amount: 0.55 } };
205	  const tubeEnv = washerTubeEnv('wall');
206	  const goldEnv = washerTubeEnv('gold');
207	  // 06/07 ring bays (unchanged): gold bands every 9 units, 4 circumferential slot rows per bay
208	  const ringSpacing = 9.0;
209	  const slotRowsPerBay = 4;
210	  // analytic strip lights along the tunnel (28 around: ref 05 shows ≈12–16 marquee spots per half-ring)
211	  const strips: TubeStrips = { count: 28, width: 0.022, intensity: 2.6, color: '#ffd9f6', alt: 0.65 };
212	  // glossy (low roughness → the strips stay crisp lengthwise streaks instead of a flat clipped sheen)
213	  const wallBase = {
214	    // pale pink F0: the saturation comes from the magenta/violet tube environment, so white strip lights
215	    // reflect as white-pink streaks (a saturated F0 turned them into clipped flat magenta)
216	    color: '#ffa8e8', emissive: '#3a0656', emissiveIntensity: 0.3, holeColor: '#0c0014',
217	    slot: 1, repeatU: 48, stagger: false,
218	    streaks: 0, metalness: 0.92, roughness: 0.1,
219	    relief: { corrugation: 0.05, bevel: 0.05, bevelWidth: 0.12 }, rimColor: '#ff5fe0', rimStrength: 0.9,
220	    envMap: tubeEnv, envMapIntensity: 1.0, farGlow: wallGlow,
221	  } as const;
222	  // STAGE ANCHORS (wave 6): the 06/07 ring bays, hood lids and slot rows are laid out from the 06 STAGE
223	  // START, not from the 05 start, so reshaping the 05 river (which changes its arc length) never slides the
224	  // 06/07 rings, lids or slot rows along the tube. The phases reproduce the pre-wave-6 layout exactly
225	  // (measured on that course: first 06/07 ring 5.5644 u after the 06 start; slot-row phase 0.96618 there).
226	  const s06 = course.stage('06').s0;
227	  const RING06_PHASE = 5.5643876;
228	  const ROW06_PHASE = 0.9661842;
229	  const rowRepeat0607 = slotRowsPerBay / ringSpacing;
230	  const rowOffset0607 = (((ROW06_PHASE - s06 * rowRepeat0607) % 1) + 1) % 1;
231	  const perfTubeMat = perforatedMetal({ ...wallBase, repeatV: rowRepeat0607, offsetV: rowOffset0607, slotHalf: [0.36, 0.12] });
232	  withTubeStrips(perfTubeMat, strips, 'attribute', 'wall');
233	  // straight-axis tunnel (05 → 07 incl. arch + plunge); the stream winds inside it
234	  // wave 9b controlled test T2 (user-directed 2026-11-16: BEFORE is the baseline, ONE geometric factor per test):
235	  // the HEIGHT of the NEAR 05 tunnel around the front ring A. Measured (tools/qa/ring_fit05.py, tools/qa/axis05.ts,
236	  // qa/pilot05/wave9b/T2/): the approved ring A centre is 59 px BELOW the vanishing point, BEFORE's 44 px ABOVE,
237	  // while rings B, C, D already sit like the approved (slightly above). Lowering the WHOLE tunnel moved B–D
238	  // away from the approved (rejected). T2 lowers only the tunnel up to ring A (26 u ahead of the eye) by
239	  // ?nearfloor05=<d> units and blends back to BEFORE before ring B (40 u): radius 7.6, ring depths and spacing,
240	  // ring B onward, the far block, camera, river and gameplay are untouched.
241	  // PROMOTED 2026-11-16 ~11:45 UTC together with T1 (user: "only promote T2 if it is genuinely closer"): default 2.0 u
242	  // with ring A at 20 u = ring A centre (502,478) r 433 vs approved (474,529) r 492 (BEFORE (505,426) r 374), its arc
243	  // meets the right edge at y 241 (approved 229, BEFORE 321); B, C, D, 06, 07 pixel-identical (qa/pilot05/wave9b/T2b/).
244	  // BEFORE = ?ringa=26&nearfloor05=0 (pixel-identical to qa/pilot05/wave9/baseline/05.png).
245	  const qaNear05 = typeof location !== 'undefined' ? Number(new URLSearchParams(location.search).get('nearfloor05') ?? 2) : 2;
246	  const NEAR_FLOOR05 = Number.isFinite(qaNear05) ? qaNear05 : 0;
247	  const sEye05 = course.marks['05_crest'] - (STAGE_CAM['05']?.back ?? 6.4);
248	  const floorExtra05 = NEAR_FLOOR05 === 0 ? undefined
249	    : (s: number) => NEAR_FLOOR05 * (1 - THREE.MathUtils.smootherstep(s, sEye05 + 28, sEye05 + 38)) * THREE.MathUtils.smoothstep(s, s05 + 2, s05 + 10);
250	  const perfPath = straightTubePath(course, s05, s08, { window: 30, taper: 14, baseRadius: tubeR, floorExtra: floorExtra05 });
251	
252	  // ---- 05 current (ref 05): long ring bays + forced-perspective far tunnel, anchored to the 05 camera ----
253	  // Ref 05 ring radii about the VP: 288,192,122,85,66,54,45 px → from the locked checkpoint eye the rings sit
254	  // at depth ≈36/55 (near bays ≈17–19 units) and then recede in ever longer bays to a small warm light.
255	  // The straight only runs ≈56 units ahead of that eye before it flares into the 06 hall, so the real bays
256	  // end with a ring at depth ≈54 (sF05) and a ForcedTunnel (tube.ts) continues the same tunnel — walls,
257	  // slot rows, rings, lid pairs, water — to a virtual depth ≈430, compressed along the eye rays into the
258	  // last ≈6 real units. If path-camera moves the checkpoint, the bays and the far section follow.
259	  const sCam05 = course.marks['05_crest'] - (STAGE_CAM['05']?.back ?? 6.4);
260	  const bay05 = 14;
261	  const sGlow05 = course.stage('06').s0 - 5.9; // the straight flares into the 06 hall after this
262	  const sF05 = Math.min(sCam05 + 54, sGlow05 - 2.5);
263	  // ring slots every bay, ending at sF05; wave 8 (path-camera request, REQUESTS.md): the real ring AT sF05 is
264	  // dropped (depth 53 → r≈189 px, ref ring #2 is r≈170) — the far block's ring at virtual depth ≈59 replaces it.
265	  // The slot list still places the lid pair camera-side of that slot and the slot-row phase.
266	  const ringSlots05: number[] = [];
267	  for (let s = sF05; s >= s05 + 2; s -= bay05) ringSlots05.unshift(s);
268	  // wave 9b — controlled geometry test T1 (user-directed 2026-11-16: BEFORE is the baseline, one factor at a time).
269	  // Measured with tools/qa/ring_fit05.py (qa/pilot05/wave9b/rings): the approved rings are ROUND — A r 492 px,
270	  // B 240, C 150, D 88 — and BEFORE draws B 228, C 153, D 96 (within −5…+9 %) but the front ring A only 374 (−24 %):
271	  // its bay slot sits 26 u ahead of the checkpoint eye (r ≈ 9724 / depth). T1 moves ONLY that ring to RING_A05_DEPTH
272	  // (20 u → r ≈ 490); tunnel radius, cross-section, camera, every other ring, the lids and the far block are untouched.
273	  // Default 20 since the T2 promotion (2026-11-16); ?ringa=26 = BEFORE. (The wave-9 oval / "big tunnel" tests are NOT in this code:
274	  // qa/pilot05/wave9b/not_merged/.)
275	  const qaNum05 = (key: string, d: number) => {
276	    const v = typeof location !== 'undefined' ? new URLSearchParams(location.search).get(key) : null;
277	    return v !== null && v !== '' && Number.isFinite(Number(v)) ? Number(v) : d;
278	  };
279	  const RING_A05_DEPTH = qaNum05('ringa', 20);
280	  // wave 9b controlled test W1 (user priority 1, 2026-11-16: glossy purple-metallic tunnel): tools/qa/diff05.py measured
281	  // the BEFORE walls too PINK (tunnel band pink 50 % vs approved 37 %) and too dull (white light streaks 0.9 % vs
282	  // 3.8 %). ?wall05=1 = ONE material factor: cooler violet wall F0 + emissive, brighter/wider/whiter lengthwise light
283	  // streaks. Geometry, rings, lids, Marble reflection map, river, camera untouched. Default 0 = BEFORE.
284	  const WALL05 = qaNum05('wall05', 0) === 1;
285	  // wave 9b controlled test G1 (user goal: polished gold rings): tools measured the ring gold (gold-mask pixels,
286	  // tunnel area) APPROVED mean (231,125,85), G/R 0.48, sat 0.66, shadow V p10 0.75 vs the game (239,154,112), 0.64,
287	  // 0.55, 0.82 = pale peach. ?gold05=1 = ONE material factor: a tone curve on the 05 ring band colour that deepens
288	  // the mid-tones toward saturated orange-gold while highlights stay bright. Default 0 = shader unchanged.
289	  const GOLD05 = qaNum05('gold05', 0) === 1;
290	  const TONE05: [number, number, number] = [1.35, 1.75, 1.3];
291	  const rings05 = ringSlots05.filter((s) => Math.abs(s - sF05) > 0.5).map((s) => (Math.abs(s - sCam05 - 26) < 3 ? sCam05 + RING_A05_DEPTH : s));
292	  // 05 walls: 7 dark capsule-slot rows per 14-unit bay, centred between the bands (rows 2 apart),
293	  // slots ≈0.6 × 0.24 units laid along the circumference (ref 05 near slots ≈10 × 28 px)
294	  // wave 7: 10 rows per bay (ref near walls show dense capsule rows, ≈25 px apart at the left edge; live had ≈45)
295	  const slotPitch05 = bay05 / 10;
296	  // ref 05 walls: deep metallic magenta/violet (#CD32AA / #992FC2), black slots, white-pink lengthwise
297	  // streaks; the warm light only at the very end (virtual depth ≳160 → halo ≲60 px about the VP)
298	  const glow05: FarGlow = { color: '#ffd796', near: 160, far: 470, strength: 1.6, mid: { color: '#8a30d2', near: 4, far: 48, amount: 0.45 } };
299	  // wave 7, tunnel surfaces only (walls, rings, lids; the far river keeps glow05): orange and earlier — the
300	  // reference throat inside the 4th ring (r < 50 px ≈ virtual depth > 200) is one continuous warm orange well
301	  // ((229,111,81) at r 32–48, (248,169,89) at r 16–24), no purple gaps between the rings
302	  const glowT05: FarGlow = { ...glow05, color: '#ff9c5a', near: 95, far: 330, strength: 1.5 };
303	  const wall05 = {
304	    // lavender F0 × the magenta tube environment → violet-magenta metal (ref #992FC2 / #CD32AA)
305	    // wave 7: no pressed-metal corrugation (its bent normals turned the strip reflections into the "marbled
306	    // swirl"), only a faint bevel; shaded slot lips instead of the bright pink dotted outline; shorter, plumper
307	    // capsules (ref median slot 25 px², elongation 4.3; live was 40 px², 8.8); bluer violet F0 (ref wall
308	    // medians (171,44,177) / (188,51,205) / (154,46,166))
