358	/**
359	 * Washer wall lids / nozzle hoods (ref 05): copper "D" hoods — a half disc with a tall polished rim band,
360	 * a softly domed top and a recessed underside with an inner lip — sticking out of BOTH side walls a bit
361	 * above eye level (≈2 and 10 o'clock seen from the rider), one symmetric pair per ring bay, so they
362	 * shrink toward the vanishing point in two rows and the rider sees the bright rim band and the dish
363	 * underneath. The straight edge of the D runs along the tube and is sunk into the wall; the hood droops
364	 * toward the stream like a spray nozzle. `skip(s, centre)` drops a lid where the stream runs too close
365	 * (06 arch climbs the wall). One instanced mesh (1 draw call).
366	 */
367	export function buildWallLids(
368	  path: TubePath,
369	  s0: number,
370	  s1: number,
371	  spacing: number,
372	  material: THREE.Material,
373	  opts: {
374	    angleDeg?: number; droopDeg?: number; size?: number; thickness?: number; stretch?: number; sink?: number;
375	    skip?: (s: number, centre: THREE.Vector3, size: number) => boolean;
376	    /** explicit lid positions along the path (default: s0, s0 + spacing, … s1) */
377	    positions?: number[];
378	    /**
379	     * 'hood' (legacy 06/07 D-hood), 'dome' (half puck with a domed cap) or 'slab' (ref 05 wave 4: a flat
380	     * copper-gold half-disc lid standing out of the wall — flat underside, rounded edges, a straight
381	     * polished rim band and a flat top, like the ref's wall-mounted nozzle lids)
382	     */
383	    shape?: 'hood' | 'dome' | 'slab';
384	    /** wave 8: lateral stretch of the wall the lids sit on (see TubeGeoOptions.oval) */
385	    oval?: (s: number) => number;
386	  } = {},
387	): THREE.InstancedMesh {
388	  const geo = wallLidGeometry(opts.shape ?? 'hood', opts.thickness ?? 0.42);
389	  const list: number[] = opts.positions ?? [];
390	  if (!opts.positions) for (let s = s0; s <= s1 + 1e-6; s += spacing) list.push(s);
391	  const n = Math.max(1, list.length) * 2;
392	  const mesh = new THREE.InstancedMesh(geo, material, n);
393	  const size = opts.size ?? 1.6;
394	  const ang = THREE.MathUtils.degToRad(opts.angleDeg ?? 18);
395	  const tilt = ang + THREE.MathUtils.degToRad(opts.droopDeg ?? 20);
396	  const c = new THREE.Vector3(), dir = new THREE.Vector3(), X = new THREE.Vector3(), Y = new THREE.Vector3(), Z = new THREE.Vector3();
397	  const basis = new THREE.Matrix4(), m = new THREE.Matrix4(), q = new THREE.Quaternion(), p = new THREE.Vector3();
398	  let k = 0;
399	  for (const s of list) {
400	    for (const side of [1, -1]) {
401	      const f = path.frame(s);
402	      const r = path.radius(s);
403	      tubeCenterAt(path, s, c);
404	      dir.copy(f.right).multiplyScalar(Math.cos(ang) * side).addScaledVector(f.up, Math.sin(ang)).normalize();
405	      const sz = size * Math.min(1.4, r / 7.6);
406	      // in the cross-section: +X points inward (radially, then drooped toward the stream), +Y is the
407	      // hood's top normal, +Z runs along the tube (the D's straight edge)
408	      X.copy(f.right).multiplyScalar(-Math.cos(tilt) * side).addScaledVector(f.up, -Math.sin(tilt)).normalize();
409	      Y.copy(f.right).multiplyScalar(-Math.sin(tilt) * side).addScaledVector(f.up, Math.cos(tilt)).normalize();
410	      Z.crossVectors(X, Y).normalize();
411	      basis.makeBasis(X, Y, Z);
412	      q.setFromRotationMatrix(basis);
413	      p.copy(c).addScaledVector(dir, r - sz * (opts.sink ?? 0.12));
414	      if (opts.oval) p.addScaledVector(f.right, (opts.oval(s) - 1) * r * Math.cos(ang) * side);
415	      if (opts.skip?.(s, p.clone().addScaledVector(X, sz * 0.5), sz)) continue;
416	      m.compose(p, q, new THREE.Vector3(sz, sz, sz * (opts.stretch ?? 1.25)));
417	      mesh.setMatrixAt(k++, m);
418	    }
419	  }
420	  mesh.count = k;
421	  mesh.instanceMatrix.needsUpdate = true;
422	  mesh.frustumCulled = false;
423	  return mesh;
424	}
