426	/** Profile of a wall lid (lathe, half revolution toward local +X), centred on its thickness. */
427	export function wallLidGeometry(shape: 'hood' | 'dome' | 'slab', h: number, segments?: number): THREE.BufferGeometry {
428	  // bottom → top so the lathe normals face outward
429	  const prof: [number, number][] = shape === 'dome'
430	    ? [
431	      [0, 0.06], [0.62, 0.05], [0.7, 0.0], [0.86, -0.04], [1.04, -0.05], [1.08, 0.0], [1.0, 0.06],
432	      [0.98, h * 0.55], [0.96, h * 0.82], [0.88, h * 1.02], [0.72, h * 1.18], [0.48, h * 1.3], [0.24, h * 1.36], [0, h * 1.38],
433	    ]
434	    : shape === 'slab'
435	      ? [
436	        // flat underside with a shallow recess and an inner ring, rounded lower edge, straight rim band,
437	        // rounded upper edge, flat (very slightly crowned) top
438	        // (edge rounding scales with the thickness so thin pucks stay valid)
439	        // wave 8: ROUNDED puck — the rim band bulges (barrel, radius 0.95 → 1.04 → 0.95) between two rounded
440	        // edges, so its smooth normal sweeps up/down across the band and the shading reads a glossy convex
441	        // copper-gold rim with a highlight low on the bulge (ref L1 at x 140: peach top edge → orange-gold → pale
442	        // yellow → white → orange-red bottom edge) instead of a flat plank; flat recessed underside; domed top
443	        [0, 0.1 * h], [0.56, 0.1 * h], [0.62, 0.03 * h], [0.88, 0.0], [0.94, 0.035 * h], [0.975, 0.12 * h],
444	        [1.015, 0.3 * h], [1.04, 0.5 * h], [1.015, 0.7 * h], [0.975, 0.86 * h], [0.93, 0.95 * h], [0.86, h],
445	        [0.55, h * 1.07], [0, h * 1.1],
446	      ]
447	      : [
448	        [0, 0.09], [0.74, 0.07], [0.82, 0.0], [0.9, -0.03], [0.97, -0.01], [1, 0.05], [1, h * 0.78], [0.95, h * 0.97], [0.82, h * 1.04], [0, h * 1.08],
449	      ];
450	  // half revolution (phi 0..π → local +X): the open cut face lies in the wall plane x = 0
451	  const geo = new THREE.LatheGeometry(prof.map(([x, y]) => new THREE.Vector2(x, y)), segments ?? (shape === 'hood' ? 28 : 24), 0, Math.PI);
452	  geo.translate(0, -h * 0.5, 0);
453	  return geo;
454	}
