456	/** Orientation of a wall lid in a tube cross-section (see buildWallLids): radial direction to the wall
457	 *  point, inward X (drooped), top normal Y, Z along the tube. */
458	export function wallLidBasis(f: Frame, side: number, angDeg: number, droopDeg: number) {
459	  const ang = THREE.MathUtils.degToRad(angDeg);
460	  const tilt = ang + THREE.MathUtils.degToRad(droopDeg);
461	  const dir = f.right.clone().multiplyScalar(Math.cos(ang) * side).addScaledVector(f.up, Math.sin(ang)).normalize();
462	  const X = f.right.clone().multiplyScalar(-Math.cos(tilt) * side).addScaledVector(f.up, -Math.sin(tilt)).normalize();
463	  const Y = f.right.clone().multiplyScalar(-Math.sin(tilt) * side).addScaledVector(f.up, Math.cos(tilt)).normalize();
464	  const Z = new THREE.Vector3().crossVectors(X, Y).normalize();
465	  return { dir, X, Y, Z };
466	}
