468	/**
469	 * Forced-perspective far section of the straight 05 tunnel (ref 05: ≈10 concentric rings converging on
470	 * one small hot spot — far more tunnel than the 72-unit straight holds before the 06 hall). A short real
471	 * funnel, calibrated for the locked 05 checkpoint camera `eye`, reproduces what a straight tunnel of the
472	 * same radius running on for `zEnd` more units would look like from there: a virtual depth Z maps to the
473	 * real depth z = Z / (1 + Z/L) and every cross-section is scaled by k(Z) = (D0 + z)/(D0 + Z) about the
474	 * eye's line of sight, so walls, slots, rings and lids project where the long tunnel would put them.
475	 * Normals stay those of the straight cylinder, so it shades like the real tube. A `fgExtra` attribute
476	 * (Z − z) lets the distance glow use the virtual depth. Morph target 0 ("open") moves every vertex just
477	 * outside the real tube wall at the same depth: the section opens like an iris as the rider arrives.
478	 */
479	export class ForcedTunnel {
480	  readonly c0: THREE.Vector3;
481	  readonly T: THREE.Vector3;
482	  readonly U: THREE.Vector3;
483	  readonly Rt: THREE.Vector3;
484	  readonly R: number;
485	  readonly D0: number;
486	  /** eye offset from the section's centre line, in the cross-section plane */
487	  readonly q: THREE.Vector3;
488	  /**
489	   * `knots` ([u, Z] pairs, increasing, starting at [0, 0]): the virtual tunnel coordinate u (continues
490	   * the real s, so slot rows / ring bays repeat every bay in u) → virtual depth Z, piecewise linear. Ref 05
491	   * draws the far bays longer than the near ones (ring radii 288,192,122,85,66,54,45 px): one ring per
492	   * knot reproduces that while every bay keeps its slot rows and lid pair. Without knots Z = u.
493	   */
494	  constructor(readonly path: TubePath, readonly sF: number, eye: THREE.Vector3, readonly L: number, readonly zEnd: number, readonly knots: [number, number][] = [], axis?: THREE.Vector3) {
495	    const f = path.frame(sF);
496	    this.c0 = tubeCenterAt(path, sF);
497	    // `axis`: direction of the straight run the camera looks down (the path's tangent at sF may already
498	    // be easing toward the next stage's axis, which would put the far vanishing point off the real one)
499	    this.T = (axis ?? f.tan).clone().normalize();
500	    this.U = f.up.clone().addScaledVector(this.T, -f.up.dot(this.T)).normalize();
501	    this.Rt = new THREE.Vector3().crossVectors(this.T, this.U).normalize();
502	    this.R = path.radius(sF);
503	    const rel = this.c0.clone().sub(eye);
504	    this.D0 = rel.dot(this.T);
505	    this.q = rel.negate().addScaledVector(this.T, this.D0); // eye − c0 minus its axial part
506	  }
507	  private interp(x: number, a: 0 | 1) {
508	    const k = this.knots, b = (1 - a) as 0 | 1;
509	    if (k.length < 2) return x;
510	    for (let i = 1; i < k.length; i++) {
511	      if (x <= k[i][a] || i === k.length - 1) {
512	        const t = (x - k[i - 1][a]) / (k[i][a] - k[i - 1][a]);
513	        return k[i - 1][b] + t * (k[i][b] - k[i - 1][b]);
514	      }
515	    }
516	    return x;
517	  }
518	  /** virtual depth Z of tunnel coordinate u (see `knots`) */
519	  zOfU(u: number) { return this.interp(u, 0); }
520	  /** tunnel coordinate u of virtual depth Z */
521	  uOfZ(Z: number) { return this.interp(Z, 1); }
522	  /** 0 = forced perspective (closed), 1 = folded away outside the real tube: the rider camera within
523	   *  `near`…`far` units (along the axis) of the section start opens it, so the ride into 06 is untouched */
524	  openFor(cam: THREE.Vector3, near = 18, far = 34) {
525	    const d = this.c0.clone().sub(cam).dot(this.T);
526	    return 1 - THREE.MathUtils.smoothstep(d, near, far);
527	  }
528	  zOf(Z: number) { return Z / (1 + Z / this.L); }
529	  kOf(Z: number) { return (this.D0 + this.zOf(Z)) / (this.D0 + Z); }
530	  /** dz/dZ: axial compression of small objects at virtual depth Z */
531	  cOf(Z: number) { const a = 1 + Z / this.L; return 1 / (a * a); }
532	  /** real position of the virtual point (depth Z, cross-section offset o from the tube centre line) */
533	  point(Z: number, o: THREE.Vector3, out = new THREE.Vector3()) {
534	    const k = this.kOf(Z);
535	    return out.copy(this.c0).addScaledVector(this.T, this.zOf(Z)).add(this.q).addScaledVector(o.clone().sub(this.q), k);
536	  }
537	  /** virtual depth Z at which the projected radius equals `frac` of the section start's */
538	  zForScreen(frac: number) { return this.D0 / frac - this.D0; }
539	  /**
540	   * Instance matrix for an object placed in the virtual straight tunnel (depth Z, offset o, rotation
541	   * basis X/Y/Z, scale s), blended toward its `open` placement (`openPos`, `openScale` multiplier).
542	   */
543	  matrix(Z: number, o: THREE.Vector3, basis: THREE.Matrix4, s: THREE.Vector3, open: number, openPos: THREE.Vector3, openScale: number, out = new THREE.Matrix4()) {
544	    const k = THREE.MathUtils.lerp(this.kOf(Z), openScale, open);
545	    const c = THREE.MathUtils.lerp(this.cOf(Z), 1, open);
546	    const p = this.point(Z, o).lerp(openPos, open);
547	    // A = k·I + (c − k)·T Tᵀ : in-plane scale k, axial scale c
548	    const T = this.T;
549	    const A = new THREE.Matrix4().set(
550	      k + (c - k) * T.x * T.x, (c - k) * T.x * T.y, (c - k) * T.x * T.z, 0,
551	      (c - k) * T.y * T.x, k + (c - k) * T.y * T.y, (c - k) * T.y * T.z, 0,
552	      (c - k) * T.z * T.x, (c - k) * T.z * T.y, k + (c - k) * T.z * T.z, 0,
553	      0, 0, 0, 1,
554	    );
555	    return out.copy(A).multiply(basis).multiply(new THREE.Matrix4().makeScale(s.x, s.y, s.z)).setPosition(p);
556	  }
557	  /** wall geometry: uv.y = sF + Z (virtual s, so slot rows continue), radial normals, morph target "open" */
558	  geometry(radial = 72, steps = 72, inset = 0.004): THREE.BufferGeometry {
559	    const rows = steps + 1;
560	    const n = rows * (radial + 1);
561	    const pos = new Float32Array(n * 3), nor = new Float32Array(n * 3), uv = new Float32Array(n * 2);
562	    const ax = new Float32Array(n * 3), au = new Float32Array(n * 3), ext = new Float32Array(n), opn = new Float32Array(n * 3);
563	    const d = new THREE.Vector3(), o = new THREE.Vector3(), p = new THREE.Vector3(), cr = new THREE.Vector3();
564	    const r0 = this.R * (1 - inset);
565	    for (let i = 0; i < rows; i++) {
566	      // uniform in projected radius (1/D): dense near the vanishing point where the rings crowd
567	      const t = i / steps;
568	      const Dv = 1 / (1 / this.D0 - t * (1 / this.D0 - 1 / (this.D0 + this.zEnd)));
569	      const Z = Math.max(0, Dv - this.D0);
570	      const z = this.zOf(Z);
571	      const sReal = this.sF + z;
572	      const fr = this.path.frame(sReal);
573	      tubeCenterAt(this.path, sReal, cr);
574	      const rOpen = this.path.radius(sReal) * 1.1 + 0.4;
575	      for (let j = 0; j <= radial; j++) {
576	        const th = -1.5 * Math.PI + (j / radial) * Math.PI * 2;
577	        d.copy(this.Rt).multiplyScalar(Math.cos(th)).addScaledVector(this.U, Math.sin(th));
578	        o.copy(d).multiplyScalar(r0);
579	        this.point(Z, o, p);
580	        const k = i * (radial + 1) + j;
581	        p.toArray(pos, k * 3);
582	        d.toArray(nor, k * 3);
583	        uv[k * 2] = j / radial; uv[k * 2 + 1] = this.sF + this.uOfZ(Z);
584	        this.T.toArray(ax, k * 3); this.U.toArray(au, k * 3);
585	        ext[k] = Z - z;
586	        // open: just outside the real (flaring) tube wall at the same depth
587	        o.copy(fr.right).multiplyScalar(Math.cos(th)).addScaledVector(fr.up, Math.sin(th)).multiplyScalar(rOpen).add(cr);
588	        o.toArray(opn, k * 3);
589	      }
590	    }
591	    const idx: number[] = [];
592	    for (let i = 0; i < rows - 1; i++) {
593	      for (let j = 0; j < radial; j++) {
594	        const a = i * (radial + 1) + j, b = a + radial + 1;
595	        idx.push(a, b, a + 1, b, b + 1, a + 1);
596	      }
597	    }
598	    const g = new THREE.BufferGeometry();
599	    g.setAttribute('position', new THREE.BufferAttribute(pos, 3));
600	    g.setAttribute('normal', new THREE.BufferAttribute(nor, 3));
601	    g.setAttribute('uv', new THREE.BufferAttribute(uv, 2));
602	    g.setAttribute('tubeAxis', new THREE.BufferAttribute(ax, 3));
603	    g.setAttribute('tubeUp', new THREE.BufferAttribute(au, 3));
604	    g.setAttribute('fgExtra', new THREE.BufferAttribute(ext, 1));
605	    g.morphAttributes.position = [new THREE.BufferAttribute(opn, 3)];
606	    g.setIndex(idx);
607	    g.computeBoundingSphere();
608	    return g;
609	  }
