611	  /**
612	   * The virtual tunnel's water surface: a flat chord across the section at `level` (relative to the tube
613	   * centre, along U) — uv.x 0..1 across, uv.y = sF + u. Because the section is a depth compression along
614	   * eye rays, this chord sits exactly on the real stream at the section start and rises above it further
615	   * in, so it takes over from the real water ribbon without a seam. Morph "open": dropped below the
616	   * real tube bottom.
617	   */
618	  chordGeometry(level: number, cols = 12, steps = 64, widthFrac = 1): THREE.BufferGeometry {
619	    const rows = steps + 1;
620	    const n = rows * (cols + 1);
621	    const pos = new Float32Array(n * 3), nor = new Float32Array(n * 3), uv = new Float32Array(n * 2);
622	    const ext = new Float32Array(n), opn = new Float32Array(n * 3);
623	    const o = new THREE.Vector3(), p = new THREE.Vector3(), cr = new THREE.Vector3();
624	    const w = Math.sqrt(Math.max(0, this.R * this.R - level * level)) * 0.995 * widthFrac;
625	    for (let i = 0; i < rows; i++) {
626	      const t = i / steps;
627	      const Dv = 1 / (1 / this.D0 - t * (1 / this.D0 - 1 / (this.D0 + this.zEnd)));
628	      const Z = Math.max(0, Dv - this.D0);
629	      const z = this.zOf(Z);
630	      const sReal = this.sF + z;
631	      const fr = this.path.frame(sReal);
632	      tubeCenterAt(this.path, sReal, cr);
633	      const rr = this.path.radius(sReal);
634	      for (let j = 0; j <= cols; j++) {
635	        const x = (j / cols * 2 - 1) * w;
636	        o.copy(this.Rt).multiplyScalar(x).addScaledVector(this.U, level);
637	        this.point(Z, o, p);
638	        const k = i * (cols + 1) + j;
639	        p.toArray(pos, k * 3);
640	        this.U.toArray(nor, k * 3);
641	        uv[k * 2] = j / cols; uv[k * 2 + 1] = this.sF + this.uOfZ(Z);
642	        ext[k] = Z - z;
643	        o.copy(cr).addScaledVector(fr.right, x * (rr / this.R)).addScaledVector(fr.up, -rr - 0.6);
644	        o.toArray(opn, k * 3);
645	      }
646	    }
647	    const idx: number[] = [];
648	    for (let i = 0; i < rows - 1; i++) {
649	      for (let j = 0; j < cols; j++) {
650	        const a = i * (cols + 1) + j, b = a + cols + 1;
651	        idx.push(a, a + 1, b, b, a + 1, b + 1);
652	      }
653	    }
654	    const g = new THREE.BufferGeometry();
655	    g.setAttribute('position', new THREE.BufferAttribute(pos, 3));
656	    g.setAttribute('normal', new THREE.BufferAttribute(nor, 3));
657	    g.setAttribute('uv', new THREE.BufferAttribute(uv, 2));
658	    g.setAttribute('fgExtra', new THREE.BufferAttribute(ext, 1));
659	    g.morphAttributes.position = [new THREE.BufferAttribute(opn, 3)];
660	    g.setIndex(idx);
661	    g.computeBoundingSphere();
662	    return g;
663	  }
664	
665	  /**
666	   * Lay instanced objects (rings, lids) into the virtual tunnel: item at tunnel coordinate `u`, offset `o`
667	   * from the centre line, rotation `basis` (local Z must run along the tube), scale `s`; when open they move
668	   * to `openPos` with in-plane scale `openScale`. Writes the instance matrices and the per-instance
669	   * `fgExtra` (virtual − real depth) the FG_VIRTUAL glow reads.
670	   */
671	  placeInstances(mesh: THREE.InstancedMesh, items: { u: number; o: THREE.Vector3; basis: THREE.Matrix4; s: THREE.Vector3; openPos: THREE.Vector3; openScale: number }[], open: number) {
672	    const m = new THREE.Matrix4();
673	    let ext = mesh.geometry.getAttribute('fgExtra') as THREE.InstancedBufferAttribute | undefined;
674	    if (!ext || ext.count < items.length) {
675	      ext = new THREE.InstancedBufferAttribute(new Float32Array(Math.max(1, items.length)), 1);
676	      mesh.geometry.setAttribute('fgExtra', ext);
677	    }
678	    items.forEach((it, i) => {
679	      const Z = this.zOfU(it.u);
680	      this.matrix(Z, it.o, it.basis, it.s, open, it.openPos, it.openScale, m);
681	      mesh.setMatrixAt(i, m);
682	      ext!.setX(i, (Z - this.zOf(Z)) * (1 - open));
683	    });
684	    mesh.count = items.length;
685	    mesh.instanceMatrix.needsUpdate = true;
686	    ext.needsUpdate = true;
687	  }
688	}
