690	/**
691	 * Ref 05 near gold frame (wave 7): the approved image is framed at the bottom by two thick gold ring segments
692	 * cut flat where they meet the stream (bottom corners) and the ∩ lip of a gold ring the stream pours over
693	 * (bottom arc). Built as one real 3D mesh in REFERENCE-PIXEL units of an 864×1536 portrait frame (origin at the
694	 * frame centre, +x right, +y up, +z toward the viewer); environment.ts places it in camera space and scales
695	 * it by the camera's FOV, so it keeps this framing on any portrait viewport. Each band is a rounded strip
696	 * (half-round bulge toward the viewer). uv = (along the arc, across the band 0 = edge toward the stream);
697	 * `framePiece` 0 = corner (uv.x = 1 at the cut), 1 = bottom lip. Measured reference edges: corner inner edge
698	 * (0,1210) · (65,1300) · (135,1400) · cut ≈ (150,1420); right mirrored; lip top edge ≈ y 1466 at x 432.
699	 */
700	export function nearFrameGeometry(): THREE.BufferGeometry {
701	  const pos: number[] = [], uv: number[] = [], piece: number[] = [], idx: number[] = [];
702	  const strip = (id: number, cx: number, cy: number, a0: number, b0: number, w: number, dir: 1 | -1, th0: number, th1: number, z0: number, nu: number, nv = 10) => {
703	    const base = pos.length / 3;
704	    for (let i = 0; i <= nu; i++) {
705	      const th = THREE.MathUtils.degToRad(th0 + ((th1 - th0) * i) / nu);
706	      for (let j = 0; j <= nv; j++) {
707	        const t = j / nv;
708	        const a = a0 + dir * t * w, b = b0 + dir * t * w;
709	        const xs = cx + a * Math.cos(th), ys = cy - b * Math.sin(th); // screen px (y down)
710	        pos.push(xs - 432, 768 - ys, z0 + w * 0.22 * Math.sin(Math.PI * t));
711	        uv.push(i / nu, t);
712	        piece.push(id);
713	      }
714	    }
715	    for (let i = 0; i < nu; i++) {
716	      for (let j = 0; j < nv; j++) {
717	        const p = base + i * (nv + 1) + j, q = p + nv + 1;
718	        idx.push(p, q, p + 1, q, q + 1, p + 1);
719	      }
720	    }
721	  };
722	  // corners: inner circle centre (432, 1060), r 457 (through the reference edge (0,1210) and the cut (150,1420)),
723	  // band 190 px outward; uv.x = 1 at the cut (θ −122° / −58°)
724	  strip(0, 432, 1060, 457, 457, 190, 1, -163, -122, 40, 36);
725	  strip(0, 432, 1060, 457, 457, 190, 1, -17, -58, 40, 36);
726	  // bottom lip: circle centre (432, 2121), top edge radius 655, band 130 px inward (downward)
727	  strip(1, 432, 2121, 655, 655, 130, -1, 122, 58, 0, 48);
728	  const g = new THREE.BufferGeometry();
729	  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
730	  g.setAttribute('uv', new THREE.Float32BufferAttribute(uv, 2));
731	  g.setAttribute('framePiece', new THREE.Float32BufferAttribute(piece, 1));
732	  g.setIndex(idx);
733	  g.computeVertexNormals();
734	  g.computeBoundingSphere();
735	  return g;
736	}
