738	/** Half-dome wall "lids"/spray heads mounted on the upper tube walls (refs 05–07). */
739	export function buildNozzles(
740	  path: TubePath,
741	  s0: number,
742	  s1: number,
743	  spacing: number,
744	  domeMat: THREE.Material,
745	  rimMat: THREE.Material,
746	  opts: { angleDeg?: number; size?: number } = {},
747	): THREE.Group {
748	  const group = new THREE.Group();
749	  const size = opts.size ?? 1.6;
750	  const dome = new THREE.SphereGeometry(1, 28, 12, 0, Math.PI * 2, 0, Math.PI / 2);
751	  dome.scale(1.25, 0.55, 0.85);
752	  const rim = new THREE.TorusGeometry(1, 0.1, 10, 40);
753	  rim.rotateX(Math.PI / 2);
754	  rim.scale(1.25, 1, 0.85);
755	  const nDomes = Math.floor((s1 - s0) / spacing) + 1;
756	  const imDome = new THREE.InstancedMesh(dome, domeMat, nDomes);
757	  const imRim = new THREE.InstancedMesh(rim, rimMat, nDomes);
758	  const m = new THREE.Matrix4();
759	  const basis = new THREE.Matrix4();
760	  const q = new THREE.Quaternion();
761	  const c = new THREE.Vector3();
762	  const dir = new THREE.Vector3();
763	  let k = 0;
764	  for (let s = s0; s <= s1 && k < nDomes; s += spacing, k++) {
765	    const f = path.frame(s);
766	    const r = path.radius(s);
767	    const side = k % 2 === 0 ? 1 : -1;
768	    const ang = THREE.MathUtils.degToRad(opts.angleDeg ?? 32);
769	    tubeCenterAt(path, s, c);
770	    dir.copy(f.right).multiplyScalar(Math.cos(ang) * side).addScaledVector(f.up, Math.sin(ang)).normalize();
771	    const p = c.clone().addScaledVector(dir, r * 0.985);
772	    const inward = dir.clone().negate();
773	    const xAxis = new THREE.Vector3().crossVectors(inward, f.tan).normalize();
774	    const zAxis = new THREE.Vector3().crossVectors(xAxis, inward).normalize();
775	    basis.makeBasis(xAxis, inward, zAxis);
776	    q.setFromRotationMatrix(basis);
777	    m.compose(p, q, new THREE.Vector3(size, size, size));
778	    imDome.setMatrixAt(k, m);
779	    imRim.setMatrixAt(k, m);
780	  }
781	  imDome.count = imRim.count = k;
782	  imDome.frustumCulled = imRim.frustumCulled = false;
783	  group.add(imDome, imRim);
784	  return group;
785	}
