33	  page.on('console', (m) => { if (m.type() === 'error') console.error('console', m.text()); });
34	  await page.goto(`${vite.url}/?qa=1&dpr=1&hide=benny,coins&waterhide=crown,spray,bubbles,splash05,splashCrown${Q ? '&' + Q : ''}`);
