36	  const meta = await page.evaluate(async () => {
37	    const R = window.__rainbow;
38	    R.goto('05');
39	    const { scene, camera, renderer, composer } = R.qa3d();
40	    const ribbon = scene.getObjectByName('water_ribbon');
41	    const far = scene.getObjectByName('tube05_far_river');
42	    const farWall = scene.getObjectByName('tube05_far_wall');
43	    const apron = scene.getObjectByName('proj05_apron');   // ?proj05=1: visual-only bank strip (id 5: t·side, s)
44	    // the game's own THREE classes, taken from live objects (no second three.js instance)
