87	    const underEnv = (o) => { if (o === apron) return false; let c = o; while (c) { if (c === envRoot) return true; c = c.parent; } return false; };
88	    for (const s of saved) { if (isFoam(s.o)) foamNames.add(s.o.name || s.o.type); }
