91	    const pass = (occ, writer) => {
92	      renderer.setRenderTarget(rt);
93	      renderer.setClearColor(0x000000, 0);
94	      renderer.clear(true, true, true);
95	      const ac = renderer.autoClear;
96	      renderer.autoClear = false;
