45	export function createProj05Apron(course: Course, path: TubePath, s0: number, s1: number, opts: { cols?: number; ds?: number; arc?: number } = {}) {
46	  const cols = opts.cols ?? 7, ds = opts.ds ?? 0.5, arc = opts.arc ?? 0.36;
47	  const rows = Math.ceil((s1 - s0) / ds) + 1;
48	  const pos: number[] = [], pj: number[] = [], idx: number[] = [];
49	  const C = new THREE.Vector3(), P = new THREE.Vector3(), d = new THREE.Vector3(), q = new THREE.Quaternion(), W = new THREE.Vector3();
50	  for (const side of [-1, 1]) {
51	    const base = pos.length / 3;
52	    for (let i = 0; i < rows; i++) {
53	      const s = Math.min(s1, s0 + i * ds);
54	      const f = course.sample(s);
55	      const hw = course.widthAt(s) / 2;
56	      P.copy(f.pos).addScaledVector(f.right, side * hw).addScaledVector(f.up, EDGE_LIFT + 0.02);   // river edge
57	      const tf = path.frame(s);
58	      tubeCenterAt(path, s, C);
59	      const R = path.radius(s) - 0.06;                                                            // just inside the wall
60	      d.copy(P).sub(C); d.addScaledVector(tf.tan, -d.dot(tf.tan)).normalize();
61	      for (let j = 0; j < cols; j++) {
62	        const t = j / (cols - 1);
63	        if (j === 0) { pos.push(P.x, P.y, P.z); }
64	        else {
65	          // rotate the edge direction up the wall about the tube axis (toward the tunnel's up side)
66	          const ang = -side * arc * ((j - 1) / (cols - 2));
67	          q.setFromAxisAngle(tf.tan, ang);
68	          W.copy(d).applyQuaternion(q).multiplyScalar(R).add(C);
69	          pos.push(W.x, W.y, W.z);
70	        }
71	        pj.push(side * t, s);
72	      }
73	    }
74	    for (let i = 0; i < rows - 1; i++) for (let j = 0; j < cols - 1; j++) {
75	      const a = base + i * cols + j, b = a + 1, c = a + cols, e = c + 1;
76	      idx.push(a, c, b, b, c, e);
77	    }
78	  }
79	  const geo = new THREE.BufferGeometry();
80	  geo.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
81	  geo.setAttribute('aPj', new THREE.Float32BufferAttribute(pj, 2));
82	  geo.setIndex(idx);
83	  geo.computeBoundingSphere();
84	  const uniforms: Record<string, THREE.IUniform> = {
85	    uPjA: { value: null }, uPjAS: { value: new THREE.Vector4(PJ_A_S0, PJ_A_S1, 1, 1) },
86	    uPjPost: { value: new THREE.Vector4(0.86, 1.36, 1.15, 0.18) }, uPjRes: { value: new THREE.Vector2(864, 1536) },
87	  };
88	  const mat = new THREE.ShaderMaterial({ uniforms, vertexShader: VERT, fragmentShader: FRAG, side: THREE.DoubleSide, fog: false });
89	  mat.polygonOffset = true; mat.polygonOffsetFactor = -1; mat.polygonOffsetUnits = -2;
90	  const mesh = new THREE.Mesh(geo, mat);
91	  mesh.name = 'proj05_apron';
92	  mesh.frustumCulled = false;
93	  const size = new THREE.Vector2();
94	  mesh.onBeforeRender = (renderer) => {
95	    const rt = renderer.getRenderTarget();
96	    if (rt) size.set(rt.width, rt.height); else renderer.getDrawingBufferSize(size);
97	    (uniforms.uPjRes.value as THREE.Vector2).copy(size);
98	    (uniforms.uPjPost.value as THREE.Vector4).x = renderer.toneMappingExposure;
99	  };
100	  // texture (absent until bake.py has produced it: then the strip simply draws nothing)
101	  proj05Pending.push(new Promise<void>((res) => {
102	    new THREE.TextureLoader().load(new URL('../../assets/textures/water05/proj05_A.png', import.meta.url).href, (t) => {
103	      t.flipY = false; t.colorSpace = THREE.NoColorSpace; t.generateMipmaps = false; t.minFilter = THREE.LinearFilter;
104	      t.needsUpdate = true;
105	      uniforms.uPjA.value = t;
106	      (uniforms.uPjAS.value as THREE.Vector4).set(PJ_A_S0, PJ_A_S1, t.image.width, t.image.height);
107	      res();
108	    }, undefined, () => res());
109	  }));
110	  mesh.visible = true;
111	  return mesh;
112	}
