227	export function channel05(course: Course, s: number): { c: number; hw: number } {
228	  const hw = course.widthAt(s) / 2;
229	  if (!FARW05) return { c: 0, hw };
230	  const st = course.stage('05');
231	  if (s <= st.s0 || s >= st.s1 + 4) return { c: 0, hw };
232	  const o = s - st.s0;                              // 05-relative arc length (the checkpoint is at o ≈ 17.75)
233	  const shL = 1.35 * smooth(25, 32, o) * (1 - smooth(39.5, 47, o));
234	  const shR = 3.7 * smooth(52, 65, o) * (1 - smooth(68.5, 76.5, o));
235	  const k = Math.min(1, (hw - 2.4) / Math.max(1e-3, (shL + shR) / 2));   // never narrower than 2.4 u half width
236	  const a = shL * Math.max(0, k), b = shR * Math.max(0, k);
237	  return { c: (a - b) / 2, hw: hw - (a + b) / 2 };
238	}
