240	export function ampAt(course: Course, s: number): number {
241	  let v = 0, w = 0;
242	  for (const st of course.stages) {
243	    const a = smooth(st.s0 - 5, st.s0 + 5, s) * (1 - smooth(st.s1 - 5, st.s1 + 5, s));
244	    if (a > 0) { v += (AMP[st.id] ?? 0.08) * a; w += a; }
